'use strict';

// MODULES //

var capitalize = require( '@stdlib/string/capitalize' );
var contains = require( '@stdlib/assert/contains' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var groupMatchesByInputType = require( './group_matches_by_input_type.js' );


// MAIN //

/**
* Extracts scalar kernel references for the JavaScript dispatch data array.
*
* @private
* @param {Array} matches - array of match entries
* @returns {string} data array content
*
* @example
* var matches = [
*     [ 'float32', 'float64', '@stdlib/math/base/special/acosd', true, 'float64', 'float64', 'stdlib_base_acosd', 'stdlib_ndarray_f_d_as_d_d' ],
*     [ 'float32', 'float32', '@stdlib/math/base/special/acosdf', false, null, null, 'stdlib_base_acosdf', 'stdlib_ndarray_f_f' ],
*     [ 'float64', 'float64', '@stdlib/math/base/special/acosd', false, null, null, 'stdlib_base_acosd', 'stdlib_ndarray_d_d' ],
*     [ 'float64', 'float32', '@stdlib/math/base/special/acosd', true, 'float64', 'float64', 'stdlib_base_acosd', 'stdlib_ndarray_d_f_as_d_d' ],
*     [ 'int32', 'float64', '@stdlib/math/base/special/acosd', true, 'float64', 'float64', 'stdlib_base_acosd', 'stdlib_ndarray_i_d_as_d_d' ]
* ];
* var result = extractDataArray( matches );
* // returns <string>
*
* // The returned string is:
* // '\t// float32\n\tacosd,\n\tacosdf,\n\n\t// float64\n\tacosd,\n\tacosd,\n\n\t// int32\n\tacosd\n'
*
* // In the template file, this renders as:
* //     // float32
* //     acosd,
* //     acosdf,
* //
* //     // float64
* //     acosd,
* //     acosd,
* //
* //     // int32
* //     acosd
*/
function extractDataArray( matches ) {
	var typeMatches;
	var importName;
	var packageMap;
	var inputType;
	var grouped;
	var pkgPath;
	var result;
	var parts;
	var match;
	var dtype;
	var jsOut;
	var idx;
	var i;
	var j;

	packageMap = {};
	for ( i = 0; i < matches.length; i++ ) {
		pkgPath = matches[ i ][ 2 ];
		if ( !hasOwnProp( packageMap, pkgPath ) ) {
			// Handle identity functions (e.g., `@stdlib/number/float64/base/identity` => `identityFloat64`):
			if ( contains( pkgPath, '/identity' ) ) {
				parts = pkgPath.split( '/' );
				dtype = parts[ parts.length - 3 ];
				importName = 'identity' + capitalize( dtype );
			} else {
				importName = pkgPath.split( '/' ).pop();
			}
			packageMap[ pkgPath ] = importName;
		}
	}

	result = groupMatchesByInputType( matches );
	grouped = result.grouped;

	jsOut = '';
	idx = 0;
	for ( i = 0; i < result.inputTypes.length; i++ ) {
		inputType = result.inputTypes[ i ];
		typeMatches = grouped[ inputType ];
		jsOut += '\t// ' + inputType + '\n';

		for ( j = 0; j < typeMatches.length; j++ ) {
			match = typeMatches[ j ];
			pkgPath = match[ 2 ];
			importName = packageMap[ pkgPath ];
			jsOut += '\t' + importName;
			idx += 1;
			if ( idx < result.totalCount ) {
				jsOut += ',\n';
			} else {
				jsOut += '\n';
			}
		}

		if ( i < result.inputTypes.length - 1 ) {
			jsOut += '\n';
		}
	}

	return jsOut;
}


// EXPORTS //

module.exports = extractDataArray;
